// src/compat/v0_3/server/push_notification/v03_push_notification_serializer.ts
var V03PushNotificationSerializer = class {
  serialize(streamResponse) {
    const payload = streamResponse.payload;
    if (!payload) {
      throw new Error("StreamResponse payload is undefined");
    }
    let legacyEvent;
    switch (payload.$case) {
      case "task":
        legacyEvent = toCompatTask(payload.value);
        break;
      case "message":
        legacyEvent = toCompatMessage(payload.value);
        break;
      case "statusUpdate":
        legacyEvent = toCompatTaskStatusUpdateEvent(payload.value);
        break;
      case "artifactUpdate":
        legacyEvent = toCompatTaskArtifactUpdateEvent(payload.value);
        break;
      default: {
        const _exhaustive = payload;
        throw new Error(`Unknown payload case: ${_exhaustive.$case}`);
      }
    }
    return {
      body: JSON.stringify(legacyEvent),
      contentType: LEGACY_JSON_CONTENT_TYPE
    };
  }
};

// src/compat/v0_3/server/push_notification/index.ts
function createLegacyAwarePushNotificationSender(pushNotificationStore, options = {}) {
  return new DefaultPushNotificationSender(pushNotificationStore, {
    ...options,
    serializers: {
      ["0.3" /* V0_3 */]: new V03PushNotificationSerializer(),
      ...options.serializers ?? {}
    }
  });
}
